import { expect, expectStatus, test } from "../../fixtures";

test("A vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const { vendor } = await factory.vendorInReview({ as: "member" });
  const before = await expectStatus<{ status: string; contact_email: string }>(
    await member.get(`/api/vendors/${vendor.id}`),
    200,
  );
  expect(before.status, "vendor is in review before the edit").toBe("in_review");

  // Act
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");
  // Re-read the stored record: the rejected edit must not have changed the contact email.
  const after = await expectStatus<{ contact_email: string }>(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(after.contact_email).toBe(before.contact_email);
});
